# 2급 CH7 동명사 (61~70) 2차 감수
X(2, 61, r="enjoy, finish, avoid, mind, keep, give up은 동명사를 목적어로 쓰고, want, hope, expect, agree, decide, plan은 to부정사를 목적어로 쓴다.",
  n=["want는 to부정사를 목적어로 쓰므로", "enjoy는 동명사를 목적어로 쓰므로", "hope는 to부정사를 목적어로 쓰므로", "expect는 to부정사를 목적어로 쓰므로", "agree는 to부정사를 목적어로 쓰므로"],
  st="① 빈칸 뒤 목적어의 형태를 본다. 동명사({0})다. → ② 동명사를 목적어로 쓰는 동사는 enjoy, finish, avoid, mind, keep, give up 등이다. want, hope, decide, plan, expect, agree, refuse, promise는 to부정사를 쓴다. → ③ 보기 가운데 동명사를 쓰는 동사는 {a}뿐이다.",
  R="spending", B="playing", C="writing", D="eating", E="waiting", F="practicing")

X(2, 62, r="동명사(구)가 주어이면 단수로 취급하여 단수 동사를 쓴다. 동사 바로 앞의 명사가 복수여도 마찬가지다.",
  n=["주어 자리에 동사원형 Drink를 쓸 수 없으므로", "coffee는 셀 수 없는 명사라 much가 맞으므로", "coffee는 셀 수 없어 복수형으로 쓰지 않으므로", "동명사구 주어는 단수 취급하므로 make를 makes로 고쳐야 하므로", "make + 목적어 + 형용사이므로 nervous가 맞으므로"],
  st="① 문장의 주어를 찾는다. 동명사구({0}) 전체가 주어다. → ② 동명사구 주어는 단수로 취급한다. {1} → ③ 동사를 단수형으로 고친 {a}가 정답이다.",
  R=("Drinking too much coffee", "동사는 make가 아니라 makes여야 한다."), B=("Playing board games with friends", "동사 바로 앞의 복수 명사 friends에 속지 않는다."), C=("Learning new words", "동사 바로 앞의 복수 명사 words에 속지 않는다."),
  D=("Watching too many videos before bed", "앞의 복수 명사 videos에 속지 않는다."), E=("Walking to school every day", "동사는 keep이 아니라 keeps여야 한다."), F=("Cooking meals for my family", "앞의 복수 명사 meals에 속지 않는다."))

X(2, 63, r="동명사는 명사처럼 주어, 동사·전치사의 목적어, 보어로 쓰인다. be동사 뒤에서 ‘~하고 있다’는 진행형을 만드는 -ing는 현재분사다.",
  n=["enjoy의 목적어인 동명사이므로", "be동사와 함께 진행형을 이루는 현재분사라 나머지와 다르므로", "finished의 목적어인 동명사이므로", "주어로 쓰인 동명사이므로", "전치사 about의 목적어인 동명사이므로"],
  st="① 밑줄 친 -ing가 명사 자리(주어, 동사·전치사의 목적어, 보어)에 있으면 동명사다. → ② be동사 뒤에서 ‘~하고 있다’로 풀리면 진행형을 만드는 현재분사다. be동사 뒤라도 ‘~하는 것’으로 풀리면 보어로 쓰인 동명사다. → ③ {n}만 ‘{0}’로 풀리는 진행형이다.",
  R="케이크를 만들고 있다", B="저녁을 준비하고 있다", C="이메일을 쓰고 있다", D="밖에서 놀고 있다", E="버스를 기다리고 있었다", F="영화를 보고 있다")

X(2, 64, r="전치사 뒤에 동사가 오면 동명사로 쓴다. look forward to, be used to의 to도 전치사다.",
  n=["look forward to의 to는 전치사라 meeting을 써야 하므로", "전치사 in 뒤에 동명사 passing을 바르게 썼으므로", "전치사 in 뒤에는 to부정사가 아니라 learning을 써야 하므로", "전치사 at 뒤에는 solving을 써야 하므로", "전치사 of 뒤에는 waiting을 써야 하므로"],
  st="① 밑줄 앞이 모두 전치사임을 확인한다({0}). → ② 전치사 뒤에 동사가 오면 동명사(-ing)로 쓴다. 동사원형이나 to부정사는 올 수 없다. → ③ 동명사를 쓴 것은 {n}({1})뿐이다.",
  R=("to, in, at, of", "in passing"), B=("at, about, of, on", "on paying"), C=("of, for, without, in, to", "in solving"), D=("about, in, of, for", "in learning"), E=("without, about, for, of", "for being"), F=("from, of, before 등", "from making"))

X(2, 65, r="be worth -ing, cannot help -ing, deny·avoid·finish + 동명사처럼 동명사만 쓰는 표현과 동사를 구별한다. regret -ing는 ‘한 일을 후회하다’이고, start는 동명사와 to부정사를 모두 쓴다.",
  pre=["문장별 판정: ⓐ O. be worth -ing. ⓑ X. cannot help -ing이므로 laughing. ⓒ X. deny + 동명사이므로 stealing. ⓓ O. regret -ing(한 일을 후회하다). ⓔ O. start는 to부정사와 동명사를 모두 쓴다. ⓕ X. avoid + 동명사이므로 eating."],
  k="틀린 문장은 ⓑ, ⓒ, ⓕ 세 개다.", n=["틀린 문장은 ⓑ, ⓒ, ⓕ 세 개이므로"] * 5,
  st="① 문장마다 동사·표현 뒤에 동명사가 와야 하는지 to부정사가 와야 하는지 본다. → ② 동명사를 쓰는 것: be worth, cannot help, deny, avoid, finish, enjoy, give up, mind, 그리고 전치사 뒤(look forward to, object to, be used to 포함). → ③ {0} 틀린 문장은 {a}이다.",
  R="ⓑ는 cannot help laughing, ⓒ는 denied stealing, ⓕ는 avoid eating으로 써야 한다.", B="ⓑ는 cannot help laughing, ⓓ는 looking forward to meeting으로 써야 한다.",
  C="ⓐ는 worth reading, ⓒ는 finished cleaning, ⓓ는 object to paying, ⓕ는 gave up smoking으로 써야 한다.", D="ⓑ는 admitted breaking, ⓒ는 worth watching, ⓓ는 used to getting, ⓔ는 gave up smoking, ⓕ는 mind opening으로 써야 한다. ⓐ만 옳다.",
  E="ⓐ는 enjoys cooking, ⓒ는 from leaving, ⓓ는 feel like taking, ⓕ는 practiced dancing으로 써야 한다.", F="ⓐ는 denied cheating, ⓕ는 suggested going으로 써야 한다.")
RV(2, 65, "E", fx=True, why="수정 예시의 정답(3개, ②)이 원문항의 정답 개수·위치와 같아, ⓓ를 틀린 문장(feel like to take)으로 바꿔 4개(③)로 했다.")

X(2, 66, r="mind는 동명사를 목적어로 쓴다. Do/Would you mind -ing?는 ‘~해 주시겠어요?’라는 부탁이다.",
  n=["mind 뒤에 동사원형을 쓸 수 없으므로", "mind는 to부정사를 목적어로 쓰지 않으므로", "mind는 동명사를 목적어로 쓰므로", "mind 뒤에 과거형을 쓸 수 없으므로", "mind 뒤에 3인칭 단수형을 쓸 수 없으므로"],
  st="① 빈칸은 동사 mind의 목적어 자리다. → ② mind는 동명사만 목적어로 쓴다. to부정사나 동사원형, 시제가 있는 동사는 올 수 없다. → ③ 괄호 속 동사({0})를 -ing로 바꾼 {a}가 정답이다.",
  R="open", B="close", C="wait", D="turn", E="move", F="help")

X(2, 67, r="keep(prevent, stop) + 목적어 + from + 동명사는 ‘~가 …하지 못하게 하다’는 뜻이다. 전치사 from 뒤에는 동명사를 쓴다.",
  n=["전치사 from 뒤에 동사원형을 쓸 수 없으므로", "전치사 뒤에 3인칭 단수형을 쓸 수 없으므로", "keep A from -ing이므로", "전치사 뒤에 to부정사를 쓸 수 없으므로", "spreaded라는 형태는 없으므로"],
  st="① 빈칸 앞이 전치사 from이다. ‘A가 ~하지 못하게 하다’는 뜻의 구문({0})이다. → ② 전치사 뒤의 동사는 동명사로 쓴다. → ③ 동사원형, to부정사, 시제가 있는 동사는 전치사 뒤에 올 수 없다. 정답은 {a}.",
  R="keep A from -ing", B="keep A from -ing", C="keep A from -ing", D="prevent A from -ing", E="keep A from -ing", F="keep A from -ing")

X(2, 68, r="feel like -ing는 ‘~하고 싶다’는 뜻이다. look forward to의 to는 전치사라 뒤에 동명사를 쓴다.",
  n=["두 자리 모두 맞지 않으므로", "look forward to 뒤에는 going을 써야 하므로", "feel like 뒤에는 to 없이 eating을 써야 하므로", "feel like eating, look forward to going으로 둘 다 동명사이므로", "두 자리 모두 맞지 않으므로"],
  st="① (A) 앞의 feel like에서 like는 전치사다. ‘~하고 싶다’는 feel like + 동명사다. → ② (B) 앞의 {0}. 뒤에 동명사가 온다. → ③ 둘 다 -ing인 {n}이 정답이다.",
  R="look forward to에서 to는 to부정사의 to가 아니라 전치사다", B="How about의 about은 전치사다", C="be interested in의 in은 전치사다", D="How about의 about은 전치사다", E="be thinking of의 of는 전치사다",
  F="prefer는 동명사를 목적어로 쓸 수 있다(보기에는 read와 reading뿐이다)")

X(2, 69, r="remember(forget) + 동명사는 ‘이미 한 일을 기억하다(잊다)’, remember(forget) + to부정사는 ‘앞으로 할 일을 기억하다(잊다)’는 뜻이다.",
  n=["(A)는 이미 한 일이고 (B)는 앞으로 할 일인데 서로 바뀌었으므로", "(B)는 앞으로 할 일이라 to부정사를 써야 하므로", "(A)는 이미 한 일이라 동명사를 써야 하므로", "이미 끈 일은 remember turning off, 앞으로 끌 일은 remember to turn off이므로", "remember 뒤에 과거형이나 동사원형을 쓸 수 없으므로"],
  st="① remember(forget) 뒤의 형태는 그 일이 이미 한 일인지 앞으로 할 일인지로 정한다. → ② (A)는 {0} 이미 한 일이다. 동명사를 쓴다. (B)는 {1} 앞으로 할 일이다. to부정사를 쓴다. → ③ 정답은 {n}.",
  R=("Yesterday가 있어", "before you go out이 있어"), B=("last night이 있어", "tonight이 있어"), C=("years ago가 있어", "today가 있어"), D=("as a child가 있어", "before you go가 있어"), E=("yesterday가 있어", "next time이 있어"),
  F=("before가 있어", "when you leave가 있어"))

X(2, 70, r="regret to-V는 ‘유감스럽게도 ~하다’, It is no use -ing는 ‘~해도 소용없다’, try -ing는 ‘시험 삼아 ~해 보다’, be busy -ing는 ‘~하느라 바쁘다’다. refuse는 to부정사를 목적어로 쓴다.",
  pre=["문장별 판정: ⓐ X. 불합격을 알리는 문맥이므로 regret to inform. ⓑ X. It is no use crying. ⓒ O. try -ing(시험 삼아 해 보다). ⓓ X. be busy -ing이므로 for를 뺀다. ⓔ X. refuse는 to부정사를 쓰므로 refused to accept."],
  k="올바르지 않은 문장은 ⓐ, ⓑ, ⓓ, ⓔ 네 개다.", n=["올바르지 않은 문장은 ⓐ, ⓑ, ⓓ, ⓔ 네 개이므로"] * 5,
  st="① 문장마다 동사 뒤 형태를 본다. regret, remember, forget, try, stop은 동명사와 to부정사에 따라 뜻이 달라지므로 문맥을 본다. → ② 관용 표현은 형태가 정해져 있다: It is no use(good) -ing, be busy -ing, be worth -ing, look forward to -ing. → ③ {0} 올바르지 않은 문장은 {a}이다.",
  R="ⓐ는 regret to inform, ⓑ는 no use crying, ⓓ는 busy preparing, ⓔ는 refused to accept로 써야 한다. ⓒ만 옳다.", B="ⓑ는 no use complaining, ⓔ는 look forward to meeting으로 써야 한다.",
  C="ⓒ만 틀렸다. stopped drinking으로 써야 한다.", D="ⓑ는 stopped talking, ⓓ는 used to working, ⓔ는 avoided answering으로 써야 한다.",
  E="ⓐ는 remembered calling, ⓓ는 no good arguing, ⓔ는 looking forward to seeing으로 써야 한다.", F="ⓔ만 틀렸다. worth reading으로 써야 한다.")
RV(2, 70, "E", fx=True, why="수정 예시의 정답(4개, ④)이 원문항의 정답 개수·위치와 같아, ⓑ를 옳은 문장(tried opening)으로 되돌려 3개(③)로 했다.")
